import{_ as s,o as i,c as e,a4 as n}from"./chunks/framework.vNSRaLQv.js";const u=JSON.parse('{"title":"HomeSense-Stdio 转交文档 - 2026-06-05","description":"","frontmatter":{"title":"HomeSense-Stdio 转交文档 - 2026-06-05","date":"2026-06-05T00:00:00.000Z"},"headers":[],"relativePath":"posts/HomeSense-Stdio-HANDOFF-2026-06-05.md","filePath":"posts/HomeSense-Stdio-HANDOFF-2026-06-05.md"}'),l={name:"posts/HomeSense-Stdio-HANDOFF-2026-06-05.md"};function p(o,a,t,c,d,r){return i(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="homesense-stdio-转交文档-2026-06-05" tabindex="-1">HomeSense-Stdio 转交文档 - 2026-06-05 <a class="header-anchor" href="#homesense-stdio-转交文档-2026-06-05" aria-label="Permalink to &quot;HomeSense-Stdio 转交文档 - 2026-06-05&quot;">​</a></h1><h2 id="_1-当前结论" tabindex="-1">1. 当前结论 <a class="header-anchor" href="#_1-当前结论" aria-label="Permalink to &quot;1. 当前结论&quot;">​</a></h2><p>当前项目已经不适合作为继续堆功能的主线代码库。</p><p>建议把 <code>D:\\files\\HomeSense-Stdio</code> 定位为 legacy/reference 仓库：保留历史实现、CLI 能力、文档和可迁移素材，但不要继续在当前混乱结构里做大规模业务演进。</p><p>下一步建议新建 v2 项目，重新建立清晰架构，再按白名单迁移必要能力。</p><p>推荐新项目位置：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>D:\\files\\HomeSense-Studio-v2</span></span></code></pre></div><p>不建议在旧仓库里建 <code>v2/</code> 子目录。旧仓库已有大量历史路由、旧文档、旧模块、lockfile 和未验证清理改动，会持续污染判断。</p><h2 id="_2-当前仓库状态" tabindex="-1">2. 当前仓库状态 <a class="header-anchor" href="#_2-当前仓库状态" aria-label="Permalink to &quot;2. 当前仓库状态&quot;">​</a></h2><p>当前仓库位置：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>D:\\files\\HomeSense-Stdio</span></span></code></pre></div><p>最近已完成并提交的 commit 链：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>5befcb1 chore: switch to pnpm monorepo + fix Nest startup</span></span>
<span class="line"><span>e55f577 refactor(nest): LegacyBridgeModule - all 21 singletons via DI</span></span>
<span class="line"><span>b1e4a7c docs: HANDOFF-4 - Nest takeover complete + CLI direction correction</span></span></code></pre></div><p><code>docs/HANDOFF-4.md</code> 已存在，但其中关于 <code>native adbkit</code> 只是辅助的表达已经不再准确。新的方向是：<code>adb-cli</code> / <code>mi-cli</code> 是经过设计的主体能力，未被设计的 native <code>adbkit</code> / native <code>miio</code> 不应该继续作为主动发现或主路径存在。</p><p>当前工作区是脏的，而且有未验证的删除和修改。不要把当前工作区视为稳定基线。</p><p>已观察到的未提交方向包括：</p><ul><li>后端 <code>device-discovery</code> Nest 模块被删除。</li><li><code>adbkit</code> / <code>miio</code> 类型声明被删除。</li><li>后端 <code>package.json</code> 和 <code>pnpm-lock.yaml</code> 已移除相关依赖。</li><li>前端部分 ADB / MI 测试页面和路由被删除。</li><li><code>DevicesView.vue</code> 已开始改成手动绑定，不再走 native ADB 扫描。</li><li><code>MiCliDetailView.vue</code> 已开始从 discover 语义改成 binding candidates 语义。</li><li><code>skills/adb-cli</code>、<code>skills/hami-cli</code>、<code>skills/sandbox-mi-cli</code>、<code>virtual-home-runtime</code> 等旧 skill/runtime 文件出现删除或归档痕迹。</li><li>存在未跟踪文档 <code>docs/DEVICE-DIGITAL-TWIN.md</code> 和 <code>docs/PYTHON-CLI-FUSION.md</code>。</li></ul><p>这些改动没有完成整体验证。后续如果继续在旧仓库收尾，第一步必须跑类型检查和测试，并清理所有残留引用。</p><h2 id="_3-已对齐的新方向" tabindex="-1">3. 已对齐的新方向 <a class="header-anchor" href="#_3-已对齐的新方向" aria-label="Permalink to &quot;3. 已对齐的新方向&quot;">​</a></h2><h3 id="_3-1-废除旧沙盒主线" tabindex="-1">3.1 废除旧沙盒主线 <a class="header-anchor" href="#_3-1-废除旧沙盒主线" aria-label="Permalink to &quot;3.1 废除旧沙盒主线&quot;">​</a></h3><p>现阶段所有旧的 sandbox、virtual device、fake home runtime 都不再作为主线设计。</p><p>正确方向不是“模拟设备”，而是“真实设备的数字孪生”：</p><ul><li>设备由用户手动注入为主。</li><li>系统通过 IP、账号、CLI、局域网探测、外部服务等观察来源补充状态。</li><li>数字孪生保存的是设备状态投影、观测记录、在线判断、能力绑定和空间位置。</li><li>后续可以扩展更多状态来源，但不能把旧沙盒当成真实设备管理核心。</li></ul><h3 id="_3-2-cli-能力定位" tabindex="-1">3.2 CLI 能力定位 <a class="header-anchor" href="#_3-2-cli-能力定位" aria-label="Permalink to &quot;3.2 CLI 能力定位&quot;">​</a></h3><p>当前已经明确：</p><ul><li><code>adb-cli</code> 是 Android/ADB 方向的主体能力。</li><li><code>mi-cli</code> 是小米方向的主体能力。</li><li>后续可能有 <code>bilibili-cli</code> 或其他外部能力模块。</li><li>native <code>adbkit</code> / native <code>miio</code> 不符合当前设计理念，不应继续作为主动发现主路径。</li></ul><p>旧说法“native adbkit 只是辅助”容易造成误解。更准确的判断是：这些 native 包不是当前设计出来的能力模块，除非未来重新设计边界，否则应该删除或归档，而不是保留在 active code path。</p><h3 id="_3-3-统一账号管理" tabindex="-1">3.3 统一账号管理 <a class="header-anchor" href="#_3-3-统一账号管理" aria-label="Permalink to &quot;3.3 统一账号管理&quot;">​</a></h3><p>需要统一认证/账号页，不要分散在各功能入口里。</p><p>第一批账号类型：</p><ul><li>小米账号</li><li>哔哩哔哩账号</li></ul><p>账号中心负责：</p><ul><li>登录状态</li><li>cookie/token/credential 管理</li><li>账号与能力模块的绑定关系</li><li>后续账号刷新、失效提示、重新认证</li></ul><h3 id="_3-4-数字孪生设备管理" tabindex="-1">3.4 数字孪生设备管理 <a class="header-anchor" href="#_3-4-数字孪生设备管理" aria-label="Permalink to &quot;3.4 数字孪生设备管理&quot;">​</a></h3><p>设备管理要增强为数字孪生中心，而不是普通设备列表。</p><p>核心能力：</p><ul><li>手动创建设备。</li><li>按 IP 判断在线。</li><li>尽可能提取设备状态。</li><li>记录观测来源和状态快照。</li><li>支持房间。</li><li>支持设备分组。</li><li>支持设备之间的简单关联。</li><li>支持 2D 房间拓扑图。</li></ul><p>拓扑方向：</p><ul><li>做 2D。</li><li>基于房间。</li><li>不做 3D。</li><li>分组优先，例如电视和机顶盒一组。</li><li>设备之间可手动建立关系。</li></ul><h2 id="_4-建议的-v2-架构" tabindex="-1">4. 建议的 v2 架构 <a class="header-anchor" href="#_4-建议的-v2-架构" aria-label="Permalink to &quot;4. 建议的 v2 架构&quot;">​</a></h2><p>v2 应该按中心化能力重建，而不是照搬旧代码。</p><p>建议四个核心中心：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>Accounts/Auth Center</span></span>
<span class="line"><span>  - Xiaomi account</span></span>
<span class="line"><span>  - Bilibili account</span></span>
<span class="line"><span>  - credentials/session lifecycle</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Device Digital Twin Center</span></span>
<span class="line"><span>  - manual devices</span></span>
<span class="line"><span>  - network endpoints/IP online state</span></span>
<span class="line"><span>  - rooms</span></span>
<span class="line"><span>  - 2D topology</span></span>
<span class="line"><span>  - groups</span></span>
<span class="line"><span>  - relations</span></span>
<span class="line"><span>  - observations</span></span>
<span class="line"><span>  - state snapshots</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Capabilities Center</span></span>
<span class="line"><span>  - adb-cli</span></span>
<span class="line"><span>  - mi-cli</span></span>
<span class="line"><span>  - bilibili-cli</span></span>
<span class="line"><span>  - external service adapters</span></span>
<span class="line"><span>  - capability bindings</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Runtime/Automation Center</span></span>
<span class="line"><span>  - workflows</span></span>
<span class="line"><span>  - agents</span></span>
<span class="line"><span>  - tasks</span></span>
<span class="line"><span>  - only consume accounts/devices/capabilities through stable APIs</span></span></code></pre></div><p>关键原则：</p><ul><li>Runtime 不能直接扫设备。</li><li>Workflow 不能直接碰账号密钥。</li><li>CLI 不能自己决定业务设备模型。</li><li>前端不能把临时 API 当业务边界。</li><li>所有真实设备状态都进入数字孪生中心统一沉淀。</li></ul><h2 id="_5-v2-推荐目录结构" tabindex="-1">5. v2 推荐目录结构 <a class="header-anchor" href="#_5-v2-推荐目录结构" aria-label="Permalink to &quot;5. v2 推荐目录结构&quot;">​</a></h2><p>推荐使用新的 pnpm monorepo：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>HomeSense-Studio-v2/</span></span>
<span class="line"><span>  apps/</span></span>
<span class="line"><span>    web/                 # Vue 3 + TypeScript Web 前端</span></span>
<span class="line"><span>    server/              # NestJS 或更轻量 HTTP API</span></span>
<span class="line"><span>  packages/</span></span>
<span class="line"><span>    domain/              # 领域模型、schema、类型、状态机</span></span>
<span class="line"><span>    db/                  # 数据库 schema、migration、repository</span></span>
<span class="line"><span>    api-client/          # 前端/Android shell 复用的 API client</span></span>
<span class="line"><span>    ui/                  # 可复用 UI 组件，谨慎抽象</span></span>
<span class="line"><span>    capabilities/        # CLI adapter 协议、能力注册、调用模型</span></span>
<span class="line"><span>  docs/</span></span>
<span class="line"><span>    ARCHITECTURE.md</span></span>
<span class="line"><span>    DEVICE-DIGITAL-TWIN.md</span></span>
<span class="line"><span>    AUTH-CENTER.md</span></span>
<span class="line"><span>    CAPABILITIES.md</span></span></code></pre></div><p>如果希望未来 Android 复用前端，v2 前端应采用 web-first、responsive-first：</p><ul><li>先做 Vue 3 + TypeScript Web App。</li><li>页面从第一天支持移动端布局。</li><li>抽出 <code>packages/domain</code> 和 <code>packages/api-client</code>，避免业务逻辑写死在浏览器页面里。</li><li>后续 Android 优先考虑 Capacitor 包装同一套 Web 前端。</li><li>只有遇到强硬件、后台常驻、系统权限等需求时，再考虑原生 Android 页面。</li></ul><p>这条路线能最大化复用前端代码，也避免现在就陷入两套 UI。</p><h2 id="_6-数据模型初稿" tabindex="-1">6. 数据模型初稿 <a class="header-anchor" href="#_6-数据模型初稿" aria-label="Permalink to &quot;6. 数据模型初稿&quot;">​</a></h2><p>数字孪生建议从以下表开始设计：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>accounts</span></span>
<span class="line"><span>account_credentials</span></span>
<span class="line"><span>account_sessions</span></span>
<span class="line"><span></span></span>
<span class="line"><span>devices</span></span>
<span class="line"><span>device_network_endpoints</span></span>
<span class="line"><span>device_capability_bindings</span></span>
<span class="line"><span>device_observations</span></span>
<span class="line"><span>device_state_snapshots</span></span>
<span class="line"><span></span></span>
<span class="line"><span>rooms</span></span>
<span class="line"><span>room_topology_layouts</span></span>
<span class="line"><span>device_topology_positions</span></span>
<span class="line"><span></span></span>
<span class="line"><span>device_groups</span></span>
<span class="line"><span>device_group_members</span></span>
<span class="line"><span>device_relations</span></span>
<span class="line"><span></span></span>
<span class="line"><span>capability_providers</span></span>
<span class="line"><span>capability_invocations</span></span></code></pre></div><p>第一阶段不要过度建模。优先保证下面这些问题能被稳定回答：</p><ul><li>这个设备是谁手动创建的？</li><li>它属于哪个房间？</li><li>它现在是否在线？</li><li>在线判断来自哪里？</li><li>它绑定了哪些能力？</li><li>最近一次观测到的状态是什么？</li><li>它和哪些设备在同一组？</li><li>它在 2D 房间图上的位置在哪里？</li></ul><h2 id="_7-迁移白名单和黑名单" tabindex="-1">7. 迁移白名单和黑名单 <a class="header-anchor" href="#_7-迁移白名单和黑名单" aria-label="Permalink to &quot;7. 迁移白名单和黑名单&quot;">​</a></h2><h3 id="_7-1-可迁移白名单" tabindex="-1">7.1 可迁移白名单 <a class="header-anchor" href="#_7-1-可迁移白名单" aria-label="Permalink to &quot;7.1 可迁移白名单&quot;">​</a></h3><p>可以从旧仓库迁移：</p><ul><li><code>adb-cli</code> 中真正可用的 CLI 能力。</li><li><code>mi-cli</code> 中真正可用的 CLI 能力。</li><li><code>docs/DEVICE-DIGITAL-TWIN.md</code> 里的数字孪生设计思想。</li><li><code>docs/PYTHON-CLI-FUSION.md</code> 里的高性能 CLI 持久化思路。</li><li>Nest 启动、DI 接管过程中得到的经验。</li><li>可独立复用的测试样例和领域名词。</li></ul><p>迁移时必须重新审查，不要整目录复制。</p><h3 id="_7-2-不应迁移黑名单" tabindex="-1">7.2 不应迁移黑名单 <a class="header-anchor" href="#_7-2-不应迁移黑名单" aria-label="Permalink to &quot;7.2 不应迁移黑名单&quot;">​</a></h3><p>不建议迁移：</p><ul><li>旧 sandbox runtime。</li><li>virtual device / fake home runtime。</li><li>native <code>adbkit</code> 主动发现链路。</li><li>native <code>miio</code> 主动发现链路。</li><li>旧 <code>device-discovery</code> 模块。</li><li>旧的分散登录入口。</li><li>为兼容历史 UI 而存在的临时 API。</li><li>含混的 skill runner 和旧 executor 文件。</li></ul><p>这些东西最多归档查看，不应该进入 v2 active path。</p><h2 id="_8-建议执行阶段" tabindex="-1">8. 建议执行阶段 <a class="header-anchor" href="#_8-建议执行阶段" aria-label="Permalink to &quot;8. 建议执行阶段&quot;">​</a></h2><h3 id="p0-冻结旧仓库" tabindex="-1">P0 - 冻结旧仓库 <a class="header-anchor" href="#p0-冻结旧仓库" aria-label="Permalink to &quot;P0 - 冻结旧仓库&quot;">​</a></h3><p>目标：让旧仓库成为参考源，而不是继续扩张。</p><p>动作：</p><ul><li>不再继续大规模重构旧仓库。</li><li>如果必须保留当前清理现场，先 commit 或 stash。</li><li>写明旧仓库只作为 legacy/reference。</li></ul><h3 id="p1-新建-v2-骨架" tabindex="-1">P1 - 新建 v2 骨架 <a class="header-anchor" href="#p1-新建-v2-骨架" aria-label="Permalink to &quot;P1 - 新建 v2 骨架&quot;">​</a></h3><p>目标：建立干净 monorepo 和基础工程约束。</p><p>动作：</p><ul><li>新建 <code>D:\\files\\HomeSense-Studio-v2</code>。</li><li>初始化 pnpm workspace。</li><li>建立 <code>apps/web</code>、<code>apps/server</code>、<code>packages/domain</code>、<code>packages/api-client</code>。</li><li>先定义领域模型和 API contract，再做页面。</li></ul><h3 id="p2-账号中心-mvp" tabindex="-1">P2 - 账号中心 MVP <a class="header-anchor" href="#p2-账号中心-mvp" aria-label="Permalink to &quot;P2 - 账号中心 MVP&quot;">​</a></h3><p>目标：统一 Xiaomi / Bilibili 账号管理。</p><p>动作：</p><ul><li>账号列表。</li><li>登录状态。</li><li>credential 存储抽象。</li><li>账号与 capability provider 绑定。</li></ul><h3 id="p3-数字孪生-mvp" tabindex="-1">P3 - 数字孪生 MVP <a class="header-anchor" href="#p3-数字孪生-mvp" aria-label="Permalink to &quot;P3 - 数字孪生 MVP&quot;">​</a></h3><p>目标：替代旧设备页。</p><p>动作：</p><ul><li>手动创建设备。</li><li>房间管理。</li><li>IP endpoint。</li><li>在线检测。</li><li>状态快照。</li><li>设备分组。</li></ul><h3 id="p4-cli-能力接入" tabindex="-1">P4 - CLI 能力接入 <a class="header-anchor" href="#p4-cli-能力接入" aria-label="Permalink to &quot;P4 - CLI 能力接入&quot;">​</a></h3><p>目标：把 <code>adb-cli</code> / <code>mi-cli</code> 作为能力提供者接入，而不是让它们支配设备模型。</p><p>动作：</p><ul><li>定义 capability provider 协议。</li><li>定义 invocation record。</li><li>设备绑定 capability。</li><li>CLI 调用结果写入 observations。</li></ul><h3 id="p5-2d-房间拓扑" tabindex="-1">P5 - 2D 房间拓扑 <a class="header-anchor" href="#p5-2d-房间拓扑" aria-label="Permalink to &quot;P5 - 2D 房间拓扑&quot;">​</a></h3><p>目标：建立房间内设备空间管理。</p><p>动作：</p><ul><li>房间画布。</li><li>设备点位。</li><li>拖拽保存位置。</li><li>分组视觉表达。</li><li>简单关系线。</li></ul><h2 id="_9-当前旧仓库收尾提醒" tabindex="-1">9. 当前旧仓库收尾提醒 <a class="header-anchor" href="#_9-当前旧仓库收尾提醒" aria-label="Permalink to &quot;9. 当前旧仓库收尾提醒&quot;">​</a></h2><p>如果下一轮仍要在旧仓库收尾，优先事项是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>pnpm install</span></span>
<span class="line"><span>pnpm -r typecheck</span></span>
<span class="line"><span>pnpm -r test</span></span></code></pre></div><p>预期可能失败，因为当前已经删除了一批 API、路由、类型声明和模块文件。</p><p>重点检查：</p><ul><li>前端是否还有 <code>api.devices</code> / <code>api.adbDevices</code> 引用。</li><li>路由是否还有已删除页面引用。</li><li>后端是否还有 <code>DeviceDiscoveryModule</code> 引用。</li><li>依赖里是否彻底移除 <code>adbkit</code> / <code>miio</code>。</li><li>skill registry 是否还引用已删除 executor。</li><li>文档是否仍误导为 native discovery 辅助方案。</li></ul><h2 id="_10-下一轮开工提示词" tabindex="-1">10. 下一轮开工提示词 <a class="header-anchor" href="#_10-下一轮开工提示词" aria-label="Permalink to &quot;10. 下一轮开工提示词&quot;">​</a></h2><p>建议下一轮直接这样开工：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>我们准备新建 HomeSense-Studio-v2，不继续在旧仓库堆功能。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请先创建 v2 架构方案和目录骨架：</span></span>
<span class="line"><span>- 新项目位置：D:\\files\\HomeSense-Studio-v2</span></span>
<span class="line"><span>- 技术路线：pnpm monorepo，Vue 3 + TypeScript Web，后端 API，shared domain/api-client</span></span>
<span class="line"><span>- 核心中心：账号中心、设备数字孪生中心、能力中心、运行自动化中心</span></span>
<span class="line"><span>- 设备方向：手动注入、IP 在线检测、房间、2D 拓扑、分组、设备关系、状态观测</span></span>
<span class="line"><span>- 能力方向：adb-cli / mi-cli 是主体能力，native adbkit / miio 不进入 active path</span></span>
<span class="line"><span>- Android 方向：web-first responsive，未来 Capacitor 复用前端</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先不要迁移旧代码，先给出 v2 的最小可运行骨架和第一阶段数据模型。</span></span></code></pre></div><h2 id="_11-最重要的判断" tabindex="-1">11. 最重要的判断 <a class="header-anchor" href="#_11-最重要的判断" aria-label="Permalink to &quot;11. 最重要的判断&quot;">​</a></h2><p>现在最关键的不是继续修补旧项目，而是把边界重新立住：</p><ul><li>账号是账号中心。</li><li>设备是数字孪生中心。</li><li>CLI 是能力中心。</li><li>自动化是消费方。</li><li>沙盒和虚拟设备不是主线。</li><li>native discovery 不是主线。</li><li>v2 应该新建在干净目录里。</li></ul><p>只要这个边界稳定，后续功能才不会再次变成大杂烩。</p>`,103)])])}const b=s(l,[["render",p]]);export{u as __pageData,b as default};
